INSERT INTO feature VALUES('run-entry','runtime','Program entry',NULL,'implemented','ordinary',NULL,'A source declaring a top-level `main` is a program: `gandr run` runs `main`, given the arguments after the path as a `List(String)` when it takes them, or handed the ambient authority, one capability no handler of the run introduced, when it takes a capability, and exits with the integer it returns or passes to `std.process.Exit.exit`, or with 0 when it returns the unit; a `main` of any other type is refused by name. A source declaring no `main` runs nothing, its last declaration included: `gandr run` refuses it, naming `def main` and pointing at `gandr check` and `gandr test`, and an expression at its top level is refused `OutOfFragment.TopLevel`. A run that reaches a hole stops there and names it where the source writes it.','surface-lowering surface-dispatcher surface-driver core-sequent','corpus/model/programs/entry.gandr corpus/model/programs/draft.gandr corpus/model/control/program-exit.gandr corpus/model/effects/hello.gandr corpus/ledger/diagnostics/EntryType.gandr corpus/ledger/diagnostics/OutOfFragment.TopLevel.gandr crates/surface-driver/tests/cli.rs::a_script_with_no_program_is_refused','corpus/model/programs/entry.gandr',NULL);
